function minTimeToType(word) {
  let seconds = 0;
  let pointer = 0;
  for (const letter of word) {
    const target = letter.charCodeAt(0) - 97;
    const direct = Math.abs(target - pointer);
    const around = 26 - direct;
    seconds += Math.min(direct, around);
    seconds += 1;
    pointer = target;
  }
  return seconds;
}

