function minTimeToType(word) {
  // Walk the pointer one letter at a time in each direction and keep the shorter walk.
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  let at = 0;
  let time = 0;
  for (const c of word) {
    let forward = 0;
    while (letters[(at + forward) % 26] !== c) forward++;
    let backward = 0;
    while (letters[(at - backward + 26) % 26] !== c) backward++;
    time += Math.min(forward, backward) + 1;
    at = letters.indexOf(c);
  }
  return time;
}

