function generate(rand, size) {
  const all = 'abcdefghijklmnopqrstuvwxyz';
  const alphabet = size === 'large' || rand() < 0.6 ? all : ['anz', 'amno', 'ayz', 'bcd'][Math.floor(rand() * 4)];
  const length = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  let word = '';
  for (let i = 0; i < length; i++) word += alphabet[Math.floor(rand() * alphabet.length)];
  return [word];
}
